"""Store-led inner pages, using confirmed business details and existing imagery."""


def about_page(icon, out, wa, photo, breadcrumb, sections, brands):
    return f'''<div class="container">{breadcrumb([('Hakkımızda', None)])}</div>
    <section class="story-opening"><div class="container story-grid">
      <div class="story-intro"><span class="eyebrow">HAKKIMIZDA · KARAKÖY, İSTANBUL</span><h1>Işıkla başlayan<br/><em>bir buluşma.</em></h1><p class="story-lead">Ünüvar Aydınlatma. Mekânınızın ışığını birlikte konuşabileceğimiz, Karaköy’de bir adres.</p><p>Emekyemez Mahallesi’ndeki mağazamızda aydınlatma ve elektrik ihtiyaçlarınız için sizlerle buluşuyoruz. Evinizin bir köşesinden çalışma alanınıza, işletmenizin girişinden günlük yaşamınıza kadar başlangıç noktamız sizin ihtiyacınız.</p><div class="story-actions"><a class="button yellow" href="/iletisim/">Mağazamıza ulaşın {icon('arrow')}</a>{out(wa(), 'Bize yazın '+icon('up'), 'text-link')}</div><div class="story-signature"><span>Ünüvar</span><small>AYDINLATMA &amp; ELEKTRİK</small></div></div>
      <figure class="story-store">{photo('store', 'Ünüvar Aydınlatma Karaköy mağazasının vitrini ve girişi', priority=True)}<figcaption><span>{icon('pin')} KARAKÖY’DEYİZ</span><strong>Kapımız, ışığa açılıyor.</strong><p>Emekyemez Mahallesi · Tutsak Sokak No:8</p></figcaption></figure>
    </div></section>
    <section class="story-details"><div class="container story-details-grid"><div><span class="eyebrow">BİZİ YAKINDAN TANIYIN</span><h2>Bir mekândan<br/> daha fazlası.</h2></div><div><h3>Günlük hayatın içinden.</h3><p>Işık; bir akşamın sakinliğine, çalışma anına ve ilk karşılaşmaya eşlik eder. Bu yüzden konuşmaya yalnızca mekânınızdan değil, orada nasıl vakit geçirdiğinizden başlarız.</p></div><div><h3>İletişim kurmak kolay.</h3><p>Bir fotoğraf, yaklaşık bir ölçü ya da aklınızdaki birkaç fikir… WhatsApp üzerinden paylaşabilir, telefonla konuşabilir veya Karaköy’de yüz yüze görüşebiliriz.</p></div></div></section>
    {sections['about']}{brands()}
    <section class="light-story content-section"><div class="container light-story-grid"><div class="light-story-visual">{photo('hero', 'Sıcak ışığın opal cam ve doğal yüzeyler üzerindeki etkisi')}</div><div class="light-story-copy"><span class="eyebrow">IŞIĞIN MEKÂNA DOKUNUŞU</span><h2>Görünüşü değiştirir.<br/><em>Hissi tamamlar.</em></h2><p>Bir alanda rahat hissetmek, bir detayı fark etmek, günün ritmine uyum sağlamak. Aydınlatmayı, mekânınızın bütününün bir parçası olarak düşünelim.</p><dl><div><dt>Atmosfer</dt><dd>Mekânınızda nasıl bir his istediğiniz.</dd></div><div><dt>Kullanım</dt><dd>Günün hangi anlarında, nasıl vakit geçirdiğiniz.</dd></div><div><dt>Uyum</dt><dd>Renkler, yüzeyler ve mekânın karakteri.</dd></div></dl>{out(wa('Merhaba, mekânım için aydınlatma hakkında görüşmek istiyorum.'), 'Fikrinizi bizimle paylaşın '+icon('up'), 'button yellow')}</div></div></section>
    {sections['social']}'''


def contact_page(icon, out, wa, photo, breadcrumb, map_panel, map_url, sections):
    return f'''<div class="container">{breadcrumb([('İletişim', None)])}</div>
    <section class="contact-opening"><div class="container"><div class="contact-title"><div><span class="eyebrow">İLETİŞİM &amp; ULAŞIM</span><h1>Bir merhaba ile<br/><em>başlayalım.</em></h1></div><p>Aklınızdaki fikri konuşalım.<br/>Telefonla, bir mesajla ya da<br/>Karaköy’de yüz yüze.</p></div>
      <div class="contact-channels"><a class="channel-card" href="tel:+905456105009"><span class="channel-symbol">{icon('phone')}</span><span><small>TELEFON</small><strong>0545 610 50 09</strong><span>Doğrudan arayın</span></span>{icon('up')}</a>{out(wa(), '<span class="channel-symbol">'+icon('wa')+'</span><span><small>WHATSAPP</small><strong>Bir mesaj uzağınızdayız.</strong><span>Fikrinizi bizimle paylaşın</span></span>'+icon('up'), 'channel-card')}<a class="channel-card" href="#magaza-konumu"><span class="channel-symbol">{icon('pin')}</span><span><small>MAĞAZA</small><strong>Karaköy, İstanbul.</strong><span>Konumu ve yol tarifini görün</span></span>{icon('arrow')}</a></div>
    </div></section>
    <section class="contact-destination content-section" id="magaza-konumu" aria-labelledby="destination-title"><div class="container"><div class="destination-heading"><div><span class="eyebrow">KARAKÖY’DE BULUŞALIM</span><h2 id="destination-title">Yolunuz bize düşsün.</h2></div>{out(map_url, 'Yol tarifi al '+icon('up'), 'button outline')}</div><div class="destination-grid">{map_panel()}<aside class="destination-store"><div class="destination-photo">{photo('store','Ünüvar Aydınlatma mağaza girişi')}</div><div class="destination-address"><span class="eyebrow">ÜNÜVAR AYDINLATMA</span><address>Emekyemez Mahallesi<br/>Tutsak Sokak No:8, 34421<br/>Beyoğlu / İstanbul</address><button class="text-button" type="button" data-copy="Ünüvar Aydınlatma, Emekyemez Mahallesi, Tutsak Sokak No:8, 34421 Beyoğlu / İstanbul">{icon('copy')} Adresi kopyala</button></div></aside></div><div class="visit-note">{icon('phone')}<p><strong>Gelmeden önce konuşalım.</strong> Ziyaret etmek istediğiniz gün ve saati <a href="tel:+905456105009">0545 610 50 09</a> numarasından teyit edebilirsiniz.</p></div></div></section>
    <section class="conversation-section content-section" aria-labelledby="conversation-title"><div class="container conversation-grid"><div class="conversation-intro"><span class="eyebrow">SÖZ SİZDE</span><h2 id="conversation-title">Mekânınızı anlatın.<br/><em>Birlikte konuşalım.</em></h2><p>Aşağıdaki alanlarla mesajınızı hazırlayıp WhatsApp’ta açabilirsiniz. Varsa mekânınızın fotoğrafını sohbet sırasında ekleyebilirsiniz.</p><ul class="conversation-tips"><li>{icon('check')} Hangi alan için düşündüğünüz</li><li>{icon('check')} İstediğiniz atmosfer</li><li>{icon('check')} Yaklaşık ölçüler veya bir fotoğraf</li></ul><a class="text-link" href="tel:+905456105009">Yazmak yerine arayın {icon('arrow')}</a></div><div class="conversation-form"><div class="composer-top"><span>{icon('wa')} WHATSAPP MESAJINIZ</span><small>Ünüvar Aydınlatma</small></div><div data-contact-composer hidden><div class="composer-fields"><label for="contact-topic">Ne hakkında görüşelim?</label><select id="contact-topic"><option>Mekânımın aydınlatması</option>Mağaza ziyareti</option>Genel bir soru</option></select><label for="contact-note">Bize kısaca anlatın <span>(isteğe bağlı)</span></label><textarea id="contact-note" rows="4" maxlength="700" placeholder="Örneğin: Salonumda daha sıcak bir atmosfer istiyorum."></textarea></div><div class="message-preview"><span>MESAJ ÖNİZLEMESİ</span><p data-contact-preview>Merhaba Ünüvar Aydınlatma, mekânımın aydınlatması hakkında görüşmek istiyorum.</p></div></div>{out(wa('Merhaba Ünüvar Aydınlatma, mekânımın aydınlatması hakkında görüşmek istiyorum.'),'WhatsApp’ta aç '+icon('up'),'button yellow composer-send')}<p class="composer-note">Mesajı WhatsApp içinde siz gönderirsiniz. Buraya yazdıklarınız bu siteye kaydedilmez.</p><noscript><p>Mesajınızı açılan WhatsApp sohbetinde yazabilirsiniz.</p></noscript></div></div></section>
    {sections['faq']}{sections['social']}'''
